import{_ as e,o,c as a,a3 as r}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Customer Portal 1.3.0 (+ Help Desk 1.15.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Customer Portal 1.3.0 (+ Help Desk 1.15.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/customer-portal-1-3-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Customer Portal 1.3.0 (+ Help Desk 1.15.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/customer-portal-1-3-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/customer-portal-1-3-0-production-readiness.md","filePath":"deployment/customer-portal-1-3-0-production-readiness.md","lastUpdated":1791474066000}'),s={name:"deployment/customer-portal-1-3-0-production-readiness.md"};function n(d,t,l,i,c,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="customer-portal-1-3-0-help-desk-1-15-0-—-production-readiness-audit" tabindex="-1">Customer Portal 1.3.0 (+ Help Desk 1.15.0) — Production Readiness Audit <a class="header-anchor" href="#customer-portal-1-3-0-help-desk-1-15-0-—-production-readiness-audit" aria-label="Permalink to &quot;Customer Portal 1.3.0 (+ Help Desk 1.15.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-08</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong></td></tr><tr><td><strong>Scope</strong></td><td>Magic-link login; portal TOTP 2FA; published Knowledge Base in portal; Help Desk customer-reply reopen + notify (<strong>help-desk 1.15.0</strong>); conversation UI polish; Settings email toggles for Help Desk events</td></tr><tr><td><strong>Catalog</strong></td><td><strong>customer-portal 1.2.0 → 1.3.0</strong>, <strong>help-desk 1.14.0 → 1.15.0</strong> (migrate-only + CatalogSeeder)</td></tr><tr><td><strong>Companion</strong></td><td><a href="./help-desk-1-15-0-production-readiness">Help Desk 1.15.0 readiness</a> · <a href="/user-guide/customer-portal">Customer Portal</a> · <a href="/deployment/upgrade">Upgrade</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Portal auth deepens with passwordless magic links (Central mail, 15 min single-use token) and Fortify TOTP 2FA on <code>PortalUser</code>. Published Knowledge Base articles are readable in the portal when soft-entitled. Help Desk <strong>closed</strong> and <strong>resolved</strong> tickets reopen automatically on customer public reply (portal or email ingest); assignees get mandatory in-app notify and optional mail (<code>email_notifications.help_desk_*</code>, defaults off). Staff Conversation / portal Support UIs use clearer chat-style threads.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (portal SPA remains isolated; no parallel staff shells)</td><td><strong>Pass</strong></td></tr><tr><td>Magic-link request always generic success; Active accounts only; Central mail</td><td><strong>Pass</strong></td></tr><tr><td>Magic-link consume single-use; challenges 2FA when enabled</td><td><strong>Pass</strong></td></tr><tr><td>Portal 2FA manage under <code>auth:portal-api</code>; challenge issues <code>portal-token</code> (no attendance)</td><td><strong>Pass</strong></td></tr><tr><td>Portal KB published-only; soft <code>knowledge-base</code> entitlement</td><td><strong>Pass</strong></td></tr><tr><td>Customer reply reopens closed <strong>and</strong> resolved → open (system actor)</td><td><strong>Pass</strong></td></tr><tr><td>In-app notify always; mail gated by prefs (default off)</td><td><strong>Pass</strong></td></tr><tr><td>Catalog migrate-only <strong>1.3.0</strong> / <strong>1.15.0</strong> + CatalogSeeder companion</td><td><strong>Pass</strong></td></tr><tr><td>Playwright headed (one session per workflow)</td><td><strong>Pass</strong> — Customer Portal <strong>3/3</strong>; Help Desk <strong>3/3</strong></td></tr><tr><td>Pest (focused Customer Portal + Help Desk reopen/notify + catalog bumps)</td><td><strong>Pass</strong></td></tr><tr><td>Docs + CHANGELOG + upgrade path</td><td><strong>Pass</strong></td></tr></tbody></table><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="closed-audit-remediations" tabindex="-1">Closed (audit remediations) <a class="header-anchor" href="#closed-audit-remediations" aria-label="Permalink to &quot;Closed (audit remediations)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>A1</td><td>Med</td><td>Portal ticket reopen e2e: same-hash navigation did not refetch closed status (<code>staleTime</code> 30s)</td><td>Workflow forces <code>page.reload()</code> after staff close before asserting reopen copy</td></tr><tr><td>A2</td><td>Low</td><td>Magic-link empty-email assertion matched field error + toast</td><td>Scoped to <code>getByRole(&#39;main&#39;)</code></td></tr></tbody></table><h3 id="accepted-intentional-ops-—-not-defects" tabindex="-1">Accepted (intentional / ops — not defects) <a class="header-anchor" href="#accepted-intentional-ops-—-not-defects" aria-label="Permalink to &quot;Accepted (intentional / ops — not defects)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Notes</th></tr></thead><tbody><tr><td>R1</td><td>Info</td><td>Full TOTP enable→challenge→login not automated in Playwright (Security page visit + Enable control asserted); Pest covers 2FA challenge paths</td></tr><tr><td>R2</td><td>Info</td><td>Portal passkeys and online checkout remain deferred</td></tr><tr><td>R3</td><td>Ops</td><td>Deploy Backend + Frontend together; migrate-only — <strong>do not</strong> <code>db:seed</code></td></tr><tr><td>R4</td><td>Info</td><td>Email ingest reopen shares <code>reopenFromCustomerReply</code> with portal; covered by Pest + service path</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Migrations: magic-login token columns; portal <code>two_factor_*</code>; catalog bumps</li><li><code>PortalAuthService</code> magic-link request/consume; <code>authenticateCredentials</code> + 2FA challenge wiring</li><li><code>PortalTwoFactorChallengeController</code> / <code>PortalTwoFactorController</code>; <code>InitializeTenancy</code> challenge tenant resolve</li><li><code>PortalKnowledgeBaseService</code> + controller + resource</li><li><code>HelpDeskTicketService::reopenFromCustomerReply</code>; <code>HelpDeskCustomerReplyNotification</code>; prefs keys</li><li>Pest: PortalAuth/TwoFactor/KnowledgeBase/HelpDesk reopen + catalog bump tests</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Magic-link request/consume pages; Security (2FA); portal KB list/view</li><li>Login 2FA challenge form; Help Desk conversation UI polish</li><li>Settings → Notifications Help Desk email toggles; <code>help_desk.customer_reply</code> registry</li><li>Playwright Customer Portal workflow extended (KB, reopen, Security, magic-link, settings toggles)</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User / developer / API / roadmap / upgrade / CHANGELOG; this readiness page + Help Desk 1.15.0 companion</li></ul><h2 id="operator-checklist" tabindex="-1">Operator checklist <a class="header-anchor" href="#operator-checklist" aria-label="Permalink to &quot;Operator checklist&quot;">​</a></h2><ol><li>Deploy Backend → <code>php artisan migrate --force</code> (<strong>do not</strong> <code>db:seed</code>)</li><li>Confirm catalog: <code>customer-portal</code> <strong>1.3.0</strong>, <code>help-desk</code> <strong>1.15.0</strong></li><li>Deploy Frontend SPA</li><li>Smoke: magic-link request → consume; Security enable 2FA → re-login challenge; portal KB when entitled; reply on closed ticket → Open + staff in-app notification; Settings Help Desk mail toggles default off</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./help-desk-1-15-0-production-readiness">Help Desk 1.15.0 readiness</a></li><li><a href="./customer-portal">Customer Portal deployment</a></li><li><a href="/changelog/">Changelog</a></li></ul>',23)])])}const u=e(s,[["render",n]]);export{h as __pageData,u as default};
